// Generate a small, non-negative indentation level to satisfy the API requirement
int level = (int)(*FUZZ_PARAM(unsigned int) % 64);  // cap to avoid excessive allocation
std::string tabs = px::Indent(level);
// Property: result length should equal level
FUZZ_ASSERT((int)tabs.size() == level, "Indent returned unexpected size");
// Optionally touch contents to keep optimizer from discarding
size_t sum = 0; for (char c : tabs) { sum += (unsigned char)c; }
(void)sum;
// Validation: level is constrained to [0,63] and we assert size==level; no persistent objects created.

// Prepare a source buffer; treat as raw bytes
std::string s = FUZZ_PARAM_STR();
const uint8_t* src = reinterpret_cast<const uint8_t*>(s.data());

// Reverse with several compile-time sizes when possible; only call if constraints are met.
if (s.size() >= 1) {
    uint8_t dst1[1];
    px::utils::ReverseBytes<1>(src, dst1);
}
if (s.size() >= 2) {
    uint8_t dst2[2];
    px::utils::ReverseBytes<2>(src, dst2);
}
if (s.size() >= 4) {
    uint8_t dst4[4];
    px::utils::ReverseBytes<4>(src, dst4);
}
if (s.size() >= 8) {
    uint8_t dst8[8];
    px::utils::ReverseBytes<8>(src, dst8);
}
// Validation: We guard each call with size checks ensuring x and y cover N bytes and are non-null.

std::string raw = FUZZ_PARAM_STR();
std::string_view sv(raw.data(), raw.size());
// Call for float and double when enough bytes are available
if (sv.size() >= sizeof(float))  { (void)px::utils::LEndianBytesToFloat<float>(sv); }
if (sv.size() >= sizeof(double)) { (void)px::utils::LEndianBytesToFloat<double>(sv); }
// Validation: Size checks ensure the first sizeof(TFloatType) bytes are readable.

