// Source buffer
std::string raw = FUZZ_PARAM_STR();
const void* p = raw.data();

// Copy into several trivially copyable types when enough bytes are present
if (raw.size() >= sizeof(uint16_t)) {
    uint16_t v16 = px::utils::MemCpy<uint16_t>(p);
    (void)v16;
}
if (raw.size() >= sizeof(uint32_t)) {
    uint32_t v32 = px::utils::MemCpy<uint32_t>(p);
    (void)v32;
}
if (raw.size() >= sizeof(double)) {
    double vd = px::utils::MemCpy<double>(p);
    (void)vd;
